// supabase/functions/_shared/video/compose.ts
//
// A video post, assembled (Lital, 13 Oct: "fix video"). Three parts, each
// made by what already does it well:
//   - the cover card and the end card are designs from the design pipeline
//     (GPT Image from the client's own posts, exact copy set in Canva, the
//     logo file placed), drawn at 9:16;
//   - the footage is generated by a video model from a written shot, with no
//     text and no logos in it (Higgsfield);
//   - ffmpeg joins them: cover, footage, end card, with short crossfades, at
//     the platform's size.
// The join runs in an Anthropic-hosted sandbox (sandbox.ts), never on a
// laptop. This file only writes the script; it is free of Deno and network
// imports so it can be tested.

export const VIDEO_SIZE = { width: 1080, height: 1920 } as const;
/** The cards are drawn at this size (multiples of 16, nearest to 9:16) and scaled to VIDEO_SIZE. */
export const CARD_SIZE = { width: 1088, height: 1936 } as const;

export const TIMING = {
  /** How long the cover holds before it fades into the footage. */
  cover: 1.8,
  /** How long the end card holds once it has faded in. */
  end: 2.8,
  /** Each crossfade. */
  fade: 0.4,
  /** Footage seconds asked of the video model. */
  footage: 8,
} as const;

export interface ComposeInput {
  coverUrl: string;
  endUrl: string;
  footageUrl: string;
  /** A signed upload URL for the finished MP4 (Supabase Storage, PUT). */
  uploadUrl: string;
}

/** Single-quote a value for bash. */
export function shellQuote(value: string): string {
  return `'${value.replace(/'/g, `'"'"'`)}'`;
}

const FIT = `scale=${VIDEO_SIZE.width}:${VIDEO_SIZE.height}:force_original_aspect_ratio=increase,crop=${VIDEO_SIZE.width}:${VIDEO_SIZE.height},setsar=1,fps=30,format=yuv420p`;

/**
 * The bash script that downloads the three parts, joins them and uploads the
 * result. Its last line is "COMPOSED <bytes> <seconds>" on success; any
 * failing command stops it (set -e) with a non-zero exit.
 */
export function composeScript(input: ComposeInput): string {
  const { cover, end, fade } = TIMING;
  return [
    "set -euo pipefail",
    "command -v ffmpeg >/dev/null || (apt-get update -qq && apt-get install -y -qq ffmpeg >/dev/null)",
    "W=$(mktemp -d) && cd \"$W\"",
    `curl -fsSL --retry 3 -o cover.png ${shellQuote(input.coverUrl)}`,
    `curl -fsSL --retry 3 -o end.png ${shellQuote(input.endUrl)}`,
    `curl -fsSL --retry 3 -o clip.mp4 ${shellQuote(input.footageUrl)}`,
    // The footage's own length decides where the end card fades in.
    "F=$(ffprobe -v error -show_entries format=duration -of csv=p=0 clip.mp4)",
    `O2=$(awk -v f="$F" 'BEGIN{printf "%.3f", ${cover - fade} + f - ${fade}}')`,
    `T=$(awk -v f="$F" 'BEGIN{printf "%.3f", ${cover} + f + ${end} - ${2 * fade}}')`,
    [
      `ffmpeg -hide_banner -loglevel error -y`,
      `-loop 1 -t ${cover} -i cover.png`,
      `-i clip.mp4`,
      `-loop 1 -t ${end} -i end.png`,
      `-f lavfi -t "$T" -i anullsrc=r=48000:cl=stereo`,
      `-filter_complex "[0:v]${FIT}[c];[1:v]${FIT},setpts=PTS-STARTPTS[f];[2:v]${FIT}[e];[c][f]xfade=transition=fade:duration=${fade}:offset=${cover - fade}[cf];[cf][e]xfade=transition=fade:duration=${fade}:offset=$O2[v]"`,
      `-map "[v]" -map 3:a -c:v libx264 -preset medium -crf 18 -pix_fmt yuv420p -r 30 -c:a aac -b:a 128k -shortest -movflags +faststart out.mp4`,
    ].join(" "),
    `curl -fsS --retry 3 -X PUT -H 'Content-Type: video/mp4' -H 'x-upsert: true' --data-binary @out.mp4 ${shellQuote(input.uploadUrl)} >/dev/null`,
    `echo "COMPOSED $(stat -c %s out.mp4) $(ffprobe -v error -show_entries format=duration -of csv=p=0 out.mp4)"`,
  ].join("\n");
}

/** The sandbox's reply, read: the finished file's size and length, or null when it did not finish. */
export function parseComposed(reply: string): { bytes: number; seconds: number } | null {
  const m = /COMPOSED\s+(\d+)\s+([\d.]+)/.exec(reply);
  if (!m) return null;
  const bytes = Number(m[1]), seconds = Number(m[2]);
  return bytes > 10_000 && seconds > 3 ? { bytes, seconds } : null;
}
